def f(g, mindim=5):
    H,W=len(g),len(g[0]); out=[r[:] for r in g]; chosen=[]
    for i in range(H):
        for j in range(W):
            c=g[i][j]
            # extend down and right as far as uniform
            h=i
            while h<H-1 and g[h+1][j]==c: h+=1
            w=j
            while w<W-1 and g[i][w+1]==c: w+=1
            if h-i+1>=mindim and w-j+1>=mindim:
                # cannot extend further (maximal in both directions)
                chosen.append((i,j,h,w,c))
