def find_regions(g):
    H,W=len(g),len(g[0])
    seen=[[False]*W for _ in range(H)]; regions=[]
    for i in range(H):
        for j in range(W):
            if not seen[i][j]:
                col=g[i][j]; stack=[(i,j)]; comp=[]; seen[i][j]=True
                while stack:
                    a,b=stack.pop(); comp.append((a,b))
                    for da,db_ in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db_
                        if 0<=x<H and 0<=y<W and not seen[x][y] and g[x][y]==col:
                            seen[x][y]=True; stack.append((x,y))
                rs=[r for r,_ in comp]; cs=[c2 for _,c2 in comp]
                r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
                cnt={}
                for i in range(r0,r1+1):
                    for j in range(c0,c1+1):
                        cnt[g[i][j]]=cnt.get(g[i][j],0)+1
                dom=max(cnt,key=lambda c:cnt[c])
                maxn=max(cnt.values()) if cnt else 1
                purity=cnt[col]/maxn
                regions.append(dict(comp=comp,col=col,r0=r0,r1=r1,c0=c0,c1=c1,purity=purity,dom=dom,cnt=cnt))
    return regions
