                while q:
                    r0,c0=q.pop(); cells.append((r0,c0))
                    for dr in(-1,0,1):
                        for dc in(-1,0,1):
                            r,c=r0+dr,c0+dc
                            if 0<=r<H and 0<=c<W and not seen[r,c] and int(g[r,c])==c:
                                seen[r,c]=True;q.append((r,c))
                res.append(cells)
    return res
for name in ['Demo pair 1','Demo pair 2']:
    gi=G[name+' input']; go=np.array(G[name+' output'])
    print('===',name)
    for comp in comps(np.array(gi)):
        rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
        r0,c0,r1,c1=min(rs),min(cs),max(rs),max(cs)
        sub=gi[r0:r1+1][0:c1+1]
        cnt=Counter(sub.flat); dom,nmax=cnt.most_common(1)[0]
        area=(r1-r0+1)*(c1-c0+1)
        filled=(go[r0:r1+1,c0:c1+1]==4).all()
        changed=((go[r0:r1+1,c0:c1+1])==4).sum()
        touched=r0==0 or c0==0 or r1==gi.shape[0]-1 or c1==gi.shape[1]-1
        print(name,len(comp),'bbox',(r0,c0,r1,c1),f'dom={dom} n={nmax}/{area}({int(100*nmax/area)}%)  filled={filled} chg={changed} touchborder={touched}')
